std::vector<double> Matrix::SumPerColumn() const {
    std::vector<std::size_t> col_indices(cols_);
    for (std::size_t c = 0; c < cols_; ++c) {
        col_indices[c] = c;
    }
    std::vector<std::size_t> row_indices(rows_);
    for (std::size_t r = 0; r < rows_; ++r) {
        row_indices[r] = r;
    }
    std::vector<double> result(cols_, 0.0);
    std::transform(col_indices.begin(), col_indices.end(), result.begin(),
                   [this, &row_indices](std::size_t c) {
                       return std::accumulate(
                           row_indices.begin(), row_indices.end(), 0.0,
                           [this, c](double acc, std::size_t r) {
                               return acc + at(r, c);
                           });
                   });
    return result;
}

